{
  "ideas": [
    {
      "title": "Magnetron-Free Solid-State RF Cooking Plate",
      "anchors": ["C1", "T1", "C2", "C3", "C4", "T2", "T3"],
      "new_nodes": [
        {"type": "Technology", "label": "GaN solid-state RF amplifier at 2.45 GHz", "detail": "Low-voltage semiconductor amplifiers with phase control replace the vacuum tube and its 4 kV supply chain."},
        {"type": "Component", "label": "Phased-array RF antenna tiles", "detail": "Small antenna panels distributed around the cavity, each driven independently."},
        {"type": "Function", "label": "Focuses RF energy onto the exact food item", "detail": "Beam steering concentrates heat on the item rather than the whole cavity, cutting heat-up time."},
        {"type": "Function", "label": "Measures food state in real time", "detail": "Reflected-power and phase sensing estimate mass and temperature, so cooking stops when ready."},
        {"type": "Constraint", "label": "Solid-state RF cost per watt still above magnetron", "detail": "Current GaN parts make a 700 W unit expensive at entry level."}
      ],
      "new_edges": [
        {"from": "C1", "to": "C-new-amp", "type": "resolves"},
        {"from": "GaN solid-state RF amplifier at 2.45 GHz", "to": "C2", "type": "resolves"},
        {"from": "Phased-array RF antenna tiles", "to": "F3", "type": "performs_function"},
        {"from": "Focuses RF energy onto the exact food item", "to": "M5", "type": "addresses_need"},
        {"from": "Measures food state in real time", "to": "X13", "type": "partially_mitigates"},
        {"from": "Measures food state in real time", "to": "M8", "type: ": "addresses_need"},
        {"from": "Solid-state RF cost per watt still above magnetron", "to": "C1", "type": "causes"}
      ],
      "rationale": "Removing the magnetron and HV transformer chain and focusing energy on the food with sensing lets cooking finish faster and without manual timing, directly saving the user's time."
    },
    {
      "title": "Self-Timing Cook-by-Sensing Door Latch",
      "anchors": ["C13", "C14", "C15", "T8", "F7"],
      "new_nodes": [
        {"type": "Technology", "label": "Capacitive food-moisture sensing through the mesh window", "detail": "Electrodes behind the mesh read dielectric change as food heats, replacing the timer dial."},
        {"type": "Component", "label": "Capacitive sensing electrode array", "detail": "Low-cost printed electrodes on the cavity wall, fed by the existing RF field."},
        {"type": "Function", "label": "Auto-sets cooking duration from food load", "detail": "Estimates time from initial dielectric state and stops automatically."}
      ],
      "new_edges": [
        {"from": "Capacitive sensing electrode array", "to": "C13", "type": "resolves"},
        {"from": "Auto-sets cooking duration from food load", "to": "F7", "type": "resolves"},
        {"from": "Auto-sets cooking duration from food load", "to": "M5", "type": "addresses_need"},
        {"from": "Capacitive food-moisture sensing through the mesh window", "to": "X13", "type": "partially_mitigates"}
      ],
      "rationale": "Users no longer need to guess and set a timer, so the appliance finishes the job without repeated attention."
    },
    {
      "title": "Stackable Parallel Cavity Pods",
      "anchors": ["C7", "C10", "C8", "X11"],
      "new_nodes": [
        {"type": "Component", "label": "Modular stackable cooking pods", "detail": "Several small cavities share one RF source through a switched waveguide manifold."},
        {"type": "Function", "label": "Heats multiple items in parallel", "detail": "Each pod cooks a separate dish simultaneously, cutting the total batch time."}
      ],
      "new_edges": [
        {"from": "Modular stackable cooking pods", "to": "X11", "type": "partially_mitigates"},
        {"from": "Heats multiple items in parallel", "to": "M5", "type": "addresses_need"},
        {"from": "Heats multiple items in parallel", "to": "M1", "type": "addresses_need"}
      ],
      "rationale": "Cooking several items at once in separate pods removes the need to run the appliance repeatedly for each dish, saving meal-prep time."
    },
    {
      "title": "Cooking Light Replaced by Projected Cook-Guide Display",
      "anchors": ["C17", "C8", "F11", "T12"],
      "new_nodes": [
        {"type": "Technology", "label": "Holographic projection onto the mesh window", "detail": "A projector shows timers, progress and recipe steps on the glass, with no lamp."},
        {"type": "Function", "label": "Guides the user through multi-step recipes", "detail": "Shows prep tasks and next steps so the user does not have to watch the food."}
      ],
      "new_edges": [
        {"from": "Holographic projection onto the mesh window", "to": "C17", "type": "resolves"},
        {"from": "Guides the user through multi-step recipes", "to": "F11", "type": "resolves"},
        {"from": "Guides the user through multi-step recipes", "to": "M5", "type": "addresses_need"},
        {"from": "Guides the user through multi-step recipes", "to": "X14", "type": "partially_mitigates"}
      ],
      "rationale": "Replacing the bulb with an on-screen guide lets the user multitask and reach the finished dish sooner."
    },
    {
      "title": "Phone-Synced Cook Trigger Replaces Dial and Button",
      "anchors": ["C13", "C14", "C15", "C24", "F9"],
      "new_nodes": [
        {"type": "Technology", "label": "Low-power wireless link to phone app", "detail": "Bluetooth or Wi-Fi lets the user set and start cooking remotely."},
        {"type": "Component", "label": "Door latch solenoid with NFC tag reader", "detail": "A tap on the door opens or closes it without a push button."},
        {"type": "Function", "label": "Starts cooking remotely from a preset", "detail": "Recipes are loaded once and launched with one tap, from any room."}
      ],
      "new_edges": [
        {"from": "Low-power wireless link to phone app", "to": "C13", "type": "resolves"},
        {"from": "Low-power wireless link to phone app", "to": "C14", "type": "resolves"},
        {"from": "Door latch solenoid with NFC tag reader", "to": "C15", "type": "resolves"},
        {"from": "Starts cooking remotely from a preset", "to": "M5", "type": "addresses_need"},
        {"from": "Starts cooking remotely from a preset", "to": "M16", "type": "addresses_need"}
      ],
      "rationale": "One-tap or remote operation means the user spends almost no time setting up the appliance, which is the fastest path to a hot meal."
    }
  ]
}

{
  "ideas": [
    {
