        {"type": "Technology", "label": "Electrochromic door glass", "detail": "Door glass darkens to opaque when RF is active so no visible-light leak or glare is needed, and clears when cooking stops."},
        {"type": "Function", "label": "Shows cooking state at a glance without any exposed light source", "detail": "Door window reports on/off state through its own tint, removing the lamp and its burn risk."}
      ],
      "new_edges": [
        {"from": "Transparent conductive oxide (ITO) film on glass", "to": "F6", "type": "performs_function"},
        {"from": "Transparent conductive oxide (ITO) film on glass", "to": "C8", "type": "has_component"},
        {"from": "Electrochromic door glass", "to": "F11", "type": "performs_function"},
        {"from": "Transparent conductive oxide (ITO) film on glass", "to": "T5", "type": "resolves"},
