        {"from": "Transparent conductive oxide (ITO) film on glass", "to": "M7", "type": "addresses_need"},
        {"from": "C17", "to": "X14", "type": "partially_mitigates"}
      ],
      "rationale": "A continuous conductive transparent window removes the mesh holes that leak microwaves and the hot lamp that can burn fingers, directly lowering radiation and burn risk for families."
    },
    {
      "title": "Solid-State Ultrasonic Ding and Touch-Free Door Release",
      "anchors": ["C22", "T19", "C15", "T18", "C13"],
      "new_nodes": [
        {"type": "Technology", "label": "Piezoelectric transducer buzzer with soft-chime tone", "detail": "A piezo element produces an adjustable, non-sharp chime, replacing the spring hammer and metal bell."},
        {"type": "Technology", "label": "Capacitive proximity sensor door release", "detail": "A capacitive pad opens the door on a light touch or wave, removing the spring lever latch that can pinch fingers."},
        {"type": "Function", "label": "Detects a hand near the door and cuts RF before any opening", "detail": "Proximity sensing gives the interlock an early stop signal, so children's hands are never near an active field."}
      ],
      "new_edges": [
        {"from": "Piezoelectric transducer buzzer with soft-chime tone", "to": "C22", "type": "resolves"},
        {"from": "Capacitive proximity sensor door release", "to": "C15", "type": "resolves"},
        {"from": "Capacitive proximity sensor door release", "to": "F10", "type": "performs_function"},
        {"from": "Capacitive proximity sensor door release", "to": "M7", "type": "addresses_need"},
        {"from": "Piezoelectric transducer buzzer with soft-chime tone", "to": "M14", "type": "addresses_need"}
      ],
      "rationale": "Replacing the pinch-prone spring latch and the mechanical striker with sensor-based release and a soft chime removes pinch and mechanical-injury hazards while keeping the end-of-cycle signal."
    },
    {
      "title": "Non-Contact Inductive Power Transfer Replacing the Mains Cord and HV Chain",
      "anchors": ["C25", "C2", "C3", "C4", "X7"],
      "new_nodes": [
        {"type": "Technology", "label": "Low-voltage gallium-nitride solid-state RF amplifier", "detail": "Semiconductor power amplifiers replace the magnetron and its 4 kV supply, so no lethal HV rail exists."},
        {"type": "Technology", "label": "Low-voltage DC bus from a sealed isolated supply", "detail": "A sealed 24 V DC supply with double insulation replaces the mains plug, transformer, and capacitor."},
        {"type": "Function", "label": "Generates RF at safe extra-low voltage", "detail": "Keeps all accessible parts under safe voltage, so electric shock and lethal stored charge are eliminated."}
      ],
      "new_edges": [
        {"from": "Low-voltage gallium-nitride solid-state RF amplifier", "to": "C1", "type": "resolves"},
        {"from": "Low-voltage gallium-nitride solid-state RF amplifier", "to": "F1", "type": "performs_function"},
        {"from": "Low-voltage DC bus from a sealed isolated supply", "to": "C2", "type": "resolves"},
        {"from": "Low-voltage DC bus from a sealed isolated supply", "to": "C25", "type": "resolves"},
        {"from": "Low-voltage gallium-nitride solid-state RF amplifier", "to": "X7", "type": "partially_mitigates"},
        {"from": "Low-voltage gallium-nitride solid-state RF amplifier", "to": "M7", "type": "addresses_need"}
      ],
      "rationale": "Removing the 4 kV high-voltage chain and the stored lethal charge from the capacitor eliminates the main electric-shock hazard while also reducing magnetron-related burn and fault risks."
    },
    {
      "title": "Self-Sensing Mesh-Free Cavity With Continuous Radiation Monitoring",
      "anchors": ["C9", "C16", "X2", "T6", "C23"],
      "new_nodes": [
        {"type": "Technology", "label": "Embedded RF leakage sensor ring in door rim", "detail": "Small diode detectors around the door gap measure leakage in real time and feed the interlock logic."},
        {"type": "Function", "label": "Continuously verifies that radiation is contained", "detail": "Stops emission and alerts the user if leakage exceeds a safe threshold, replacing passive trust in the choke seal."}
      ],
      "new_edges": [
        {"from": "Embedded RF leakage sensor ring in door rim", "to": "C9", "type": "resolves"},
        {"from": "Embedded RF leakage sensor ring in door rim", "to": "F6", "type": "performs_function"},
        {"from": "Embedded RF leakage sensor ring in door rim", "to": "F10", "type": "enables_function"},
        {"from": "Embedded RF leakage sensor ring in door rim", "to": "X2", "type": "partially_mitigates"},
        {"from": "Embedded RF leakage sensor ring in door rim", "to": "M7", "type": "addresses_need"}
      ],
      "rationale": "Replacing a passive choke seal with a live leakage detector turns an assumed safety margin into a verified one, giving families proof and automatic shutdown against radiation exposure."
    },
    {
      "title": "Cool-Touch Dielectric Exterior Shell Replacing Steel Wrapper and Vents",
      "anchors": ["C23", "C27", "C18", "C24", "C10"],
      "new_nodes": [
        {"type": "Technology", "label": "Aerogel-insulated polymer composite shell", "detail": "Low-conductivity insulating composite shell keeps outer surface below 45 C and is non-conductive."},
        {"type": "Technology", "label": "Passive heat-pipe cooling through the base", "detail": "Heat pipes move magnetron heat to a sealed base fin, removing the need for an exposed fan and louvres."},
        {"type": "Function", "label": "Keeps exterior safe to touch and sealed against fingers", "detail": "Removes louvres and fan openings through which children could reach live or hot parts."}
      ],
      "new_edges": [
        {"from": "Aerogel-insulated polymer composite shell", "to": "C23", "type": "resolves"},
        {"from": "Aerogel-insulated polymer composite shell", "to": "C27", "type": "resolves"},
        {"from": "Passive heat-pipe cooling through the base", "to": "C18", "type": "resolves"},
        {"from": "Passive heat-pipe cooling through the base", "to": "F13", "type": "performs_function"},
        {"from": "Aerogel-insulated polymer composite shell", "to": "M7", "type": "addresses_need"},
        {"from": "Passive heat-pipe cooling through the base", "to": "F14", "type": "enables_function"}
      ],
      "rationale": "A cool, sealed, non-conductive exterior with no open louvres or fan removes burn and finger-contact hazards and keeps children away from hot or electrically live surfaces."
    }
  ]
